سن التعامل مع الناس.", "M": ["عدالة الجزاء", "الدنيا مزرعة الآخرة", "إكرام الضيف، عدم أذى الجار، قول الخير أو الصمت"], "X": "من يعلم أن كل عمل سيحاسب عليه يراقب نفسه، فيحسن إلى الناس ويتجنب الظلم. ومن ينسى ذلك قد يفعل الشر ولا يبالي.", "EX": [["ما صفات المؤمنين باليوم الآخر الواردة في الحديث؟", "إكرام الضيف، وعدم إيذاء الجار، وقول الخير أو الصمت"], ["انطلاقا من سورة «الماعون» بيّن أثر التكذيب باليوم الآخر في العلاقات بين الناس.", "المكذب بالدين يدفع اليتيم بقسوة ولا يحث على إطعام المسكين، فتفسد علاقات التراحم والتعاون في المجتمع"], ["عدّد الآثار التي يتركها الإيمان باليوم الآخر في الفرد والمجتمع.", "في الفرد: الإخلاص والاستعداد للقاء الله والحرص على الصالحات. في المجتمع: العدل والتراحم وأداء الحقوق وتجنب الظلم والفساد"], ["صف سلوك إنسان يؤمن باليوم الآخر ويتذكره دائما.", "يؤدي واجباته بإخلاص، يصدق في القول، يكرم ضيفه ويحسن إلى جاره، ويكثر من الأعمال الصالحة ويبتعد عن الظلم والغيبة"]]}, {"n": 8, "m": 2, "i": "📝", "t": "الحصيلة وأقوّم تعلماتي: اليوم الآخر", "B": [["الخلاصة", ["الإيمان باليوم الآخر واجب، وقد ربطه الله بالإيمان بالله في آيات كثيرة لعظمه", "ذكر القرآن حقائق اليوم الآخر: البعث، الحشر، إقامة الشهود، الحساب، الصراط، الجنة، النار"]], ["ثمرته", ["إذا تحقق الإيمان في القلب أثمر ثمارا جليلة تنعكس إيجابا على السلوك والحياة"]], ["سور القيامة", ["سمّى القرآن عدة سور بأسماء يوم القيامة: التغابن، الانفطار، التكوير، الغاشية، الزلزلة"]], ["دعاء", ["﴿ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار﴾"]]], "K": "الإيمان باليوم الآخر أصل من أصول الإيمان وسبب لاستقامة السلوك.", "M": ["البعث ← الحشر ← الشهود ← الحساب ← الصراط ← الجنة/النار", "سور: التغابن، الانفطار، التكوير، الغاشية، الزلزلة", "الثمرة: استقامة السلوك"], "X": "لخّص الدرس: يوم يقوم فيه الناس للحساب. ثم من آمن به عمل لأجله، ومن غفل عنه ضيّع نفسه.", "EX": [["الموت والحياة مظهران من مظاهر قدرة الله. فما الحكمة من الموت؟ وهل هو النهاية؟", "الحكمة: أن الدنيا دار اختبار وليست دار بقاء، فيستعد الإنسان للقاء الله. وليس الموت نهاية بل انتقال إلى الحياة الآخرة (القبر ثم البعث والحساب)"], ["ما معنى اليوم الآخر؟ وما مراحله بالترتيب؟", "هو يوم القيامة وما بعده. مراحله: البعث، الحشر، إقامة الشهود، الحساب، الميزان، الصراط، ثم الجنة أو النار"], ["سمّيت عدة سور بأسماء يوم القيامة. اذكر ثلاثا منها.", "التغابن والانفطار والتكوير (وكذلك الغاشية والزلزلة)"], ["وضعية إدماجية: زميلك سلوكه غير أخلاقي ويقول إنه مؤمن باليوم الآخر. اشرح له الصلة.", "الإيمان باليوم الآخر الحقيقي يدفع إلى الأخلاق الحسنة، فمن يعلم أنه سيحاسب على أعماله لا يظلم ولا يؤذي. فالسلوك السيئ دليل على ضعف الإيمان، ويجب أن يتوب ويصلح ويتذكر الحساب (كما في سورة الماعون وحديث الجار والضيف)"]]}, {"n": 9, "m": 3, "i": "🕋", "t": "الحج: تعريفه وحكمه وشروطه", "B": [["التعريف", ["لغة: القصد", "اصطلاحا: قصد بيت الله الحرام لأداء مناسك الحج في مكان معلوم ووقت معلوم"]], ["الدليل", ["﴿ولله على الناس حج البيت من استطاع إليه سبيلا﴾ (آل عمران 97)", "«بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمدا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وحج البيت، وصوم رمضان» (متفق عليه)"]], ["الحكم", ["الحج ركن من أركان الإسلام الخمسة", "فرض على المسلم المستطيع مرة في العمر"]], ["الشروط", ["الإسلام، العقل، البلوغ", "الاستطاعة: القدرة المالية والصحية والوصول إلى مكة", "وجود المحرم للمرأة أو الرفقة المأمونة"]]], "K": "الحج قصد بيت الله الحرام لأداء المناسك، وهو الركن الخامس، يجب بشروط: الإسلام والعقل والبلوغ والاستطاعة.", "M": ["الحج = قصد مكان معلوم في وقت معلوم", "شروطه: إسلام، عقل، بلوغ، استطاعة", "للمرأة: محرم أو رفقة مأمونة"], "X": "الحج رحلة عبادة إلى مكة مرة في العمر لمن استطاع. ولا يجب على من عجز عنه ماديا أو صحيا.", "EX": [["ما المقصود بالحج لغة واصطلاحا؟", "لغة: القصد. اصطلاحا: قصد بيت الله الحرام لأداء مناسك الحج في مكان معلوم ووقت معلوم"], ["ما شروط وجوب الحج؟ وماذا نقصد بالاستطاعة؟", "الإسلام، العقل، البلوغ، الاستطاعة. والاستطاعة: القدرة المالية والصحية والقدرة على الوصول إلى مكة. وتزيد المرأة بوجود المحرم أو الرفقة المأمونة"], ["اذكر دليلا على فرضية الحج.", "قوله تعالى: ﴿ولله على الناس حج البيت من استطاع إليه سبيلا﴾ (آل عمران 97)، وحديث «بني الإسلام على خمس...» وفيه «وحج البيت»"]]}, {"n": 10, "m": 3, "i": "🗺️", "t": "مواقيت الحج وأنواعه", "B": [["الميقات الزماني", ["يبدأ وقت الحج من أول يوم من شهر شوال", "إلى نهاية أيام التشريق: 11 و12 و13 من ذي الحجة"]], ["الميقات المكاني", ["مكة: أهلها", "ذو الحليفة (أبيار علي): أهل المدينة ومن مرّ بها", "الجحفة: أهل مصر والشام والمغرب العربي ومن مرّ بها", "يلملم: أهل اليمن والهند", "قرن المنازل: أهل نجد", "ذات عرق: أهل العراق والشرق الأقصى"]], ["أنواع الحج", ["الإفراد: نية الحج وحده، ثم الاعتمار بعد الفراغ من مناسك الحج", "التمتع: نية العمرة وحدها ثم الحج", "القِران: نية الحج والعمرة معا"]]], "K": "للحج ميقات زماني (شوال إلى 13 ذي الحجة) وميقات مكاني لكل بلد، وله ثلاثة أنواع: إفراد وتمتع وقِران.", "M": ["زمانا: أول شوال ← 13 ذي الحجة", "مكانا: ذو الحليفة، الجحفة، يلملم، قرن المنازل، ذات عرق", "أنواعه: إفراد، تمتع، قران"], "X": "الميقات المكاني كحدود لا يتجاوزها من يريد الحج دون إحرام. وأهل الجزائر (المغرب العربي) يحرمون من الجحفة أو ما يحاذيها.", "EX": [["من أين كان إحرام النبي ﷺ وأصحابه؟", "من ذي الحليفة (ميقات أهل المدينة المعروف بأبيار علي)"], ["اربط كل ميقات بمن يحرم منه: ذو الحليفة، الجحفة، يلملم، قرن المنازل، ذات عرق.", "ذو الحليفة: أهل المدينة. الجحفة: أهل مصر والشام والمغرب العربي. يلملم: أهل اليمن والهند. قرن المنازل: أهل نجد. ذات عرق: أهل العراق والشرق الأقصى"], ["ما الفرق بين التمتع والإفراد؟", "التمتع: نية العمرة وحدها ثم الحج. الإفراد: نية الحج وحده ثم الاعتمار بعد الفراغ منه"]]}, {"n": 11, "m": 3, "i": "🧱", "t": "أركان الحج وواجباته ومحرماته", "B": [["أركان الحج (4)", ["الإحرام: نية الدخول في الحج وفق المواقيت الزمانية والمكانية", "الوقوف بعرفة: الحضور فيها طيلة اليوم التاسع من ذي الحجة", "طواف الإفاضة: بعد نحر الهدي ورمي جمرة العقبة والحلق أو التقصير", "السعي بين الصفا والمروة: سبعة أشواط ابتداء بالصفا وانتهاء بالمروة"]], ["الواجبات", ["التجرد من الثياب المخيطة والأشياء المحيطة بالعضو", "الإحرام من الميقات المكاني", "التلبية من بداية الإحرام إلى زوال يوم عرفة", "طواف القدوم وصلاة ركعتين بعده خلف المقام والسعي بعده", "النزول بمزدلفة (والمغرب والعشاء جمعا وقصرا)", "المبيت بمنى ثلاث ليال أو ليلتين لمن تعجل", "رمي الجمرات الثلاث سبع حصيات لكل جمرة أيام التشريق من الزوال إلى الغروب"]], ["حكم الواجب", ["هي مناسك يمكن جبرها (بالفدية) في حال تركها", "بخلاف الأركان التي لا يصح الحج إلا بها"]], ["محرمات الحج", ["صيد الحيوان البري والأكل منه أو قتل أي حيوان", "قص الشعر وتقليم الأظافر واستعمال العطر", "قطع أشجار مكة أو نباتها", "عقد الزواج"]]], "K": "الأركان الأربعة: الإحرام، الوقوف بعرفة، طواف الإفاضة، السعي. وبعدها الواجبات التي تُجبر، ثم المحرمات.", "M": ["الأركان: إحرام + وقوف بعرفة + طواف إفاضة + سعي", "الواجبات تُجبر عند الترك", "المحرمات: صيد، قص شعر وأظافر وعطر، قطع شجر مكة، عقد الزواج", "الركن لا يصح الحج بدونه"], "X": "الركن مثل أساس البيت: إذا سقط سقط الحج. والواجب مثل جدرانه: إن نقص جُبر بدم. أما المحرمات فهي ما يُمنع منه المُحرِم.", "EX": [["حاج لم يطف بعد رمي الجمرات ونحر الهدي. ماذا نسمي هذا الطواف؟ وهل يصح حج من لم يقم به؟", "هو طواف الإفاضة. وهو ركن من أركان الحج، فلا يصح الحج بدونه، ويجب أن يأتي به الحاج"], ["ما الفرق بين الركن والواجب في الحج؟", "الركن لا يصح الحج إلا بالإتيان به (إحرام، وقوف بعرفة، طواف الإفاضة، سعي). الواجب يمكن جبره بالفدية في حال تركه"], ["اذكر خمسة من محرمات الحج.", "صيد البر، قص الشعر، تقليم الأظافر، استعمال العطر، قطع أشجار مكة، عقد الزواج (يكفي خمسة)"]]}, {"n": 12, "m": 3, "i": "🚶", "t": "كيفية أداء مناسك الحج مرتبة", "B": [["قبل أيام الحج", ["التجرد من المخيط (الرجل بلباس إحرام من قطعتين)", "الإحرام من الميقات والتلبية: «لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك»"]], ["بعد الوصول إلى مكة", ["طواف القدوم سبعة أشواط", "صلاة ركعتين عند مقام إبراهيم عليه السلام", "السعي بين الصفا والمروة سبعة أشواط"]], ["8 ذو الحجة: يوم التروية", ["الذهاب إلى منى والمبيت بها وصلاة فجر اليوم التاسع بها"]], ["9 ذو الحجة: عرفة", ["الوقوف بعرفة طيلة اليوم (أعظم أركان الحج)", "صلاة الظهر والعصر جمع تقديم وقصرا", "بعد الغروب التوجه إلى مزدلفة: المغرب والعشاء معا وجمع حصيات الرمي"]], ["10 ذو الحجة: يوم النحر", ["رمي جمرة العقبة بسبع حصيات والتكبير عند كل حصاة", "ذبح الهدي، ثم الحلق أو التقصير", "طواف الإفاضة بالبيت"]], ["أيام التشريق", ["المبيت بمنى ورمي الجمرات الثلاث", "الدعاء والوقوف بعد كل رمي", "عند العودة: طواف الوداع سبعة أشواط"]]], "K": "يبدأ الحج بالإحرام ثم الطواف والسعي، فمنى فعرفة فمزدلفة فرمي جمرة العقبة والنحر والحلق وطواف الإفاضة، ثم الرمي بمنى وطواف الوداع.", "M": ["إحرام ← طواف القدوم ← سعي ← 8: منى ← 9: عرفة ← مزدلفة ← 10: رمي + نحر + حلق + إفاضة ← تشريق: رمي ← وداع"], "X": "الحج برنامج مرتب بالأيام: أيام 8 و9 و10 هي المحور (منى، عرفة، مزدلفة)، ثم رمي الجمرات في أيام التشريق.", "EX": [["رتّب أفعال الحج من الوقوف بعرفة إلى أيام التشريق.", "الوقوف بعرفة (9 ذو الحجة) ← النزول بمزدلفة (المغرب والعشاء) ← رمي جمرة العقبة والنحر والحلق (10) ← طواف الإفاضة ← المبيت بمنى ورمي الجمرات الثلاث في أيام التشريق"], ["متى يذهب الحاج إلى منى؟ وماذا يسمى هذا اليوم؟", "في اليوم الثامن من ذي الحجة، ويسمى يوم التروية"], ["ما صيغة التلبية؟", "«لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك»"], ["كم حصاة يرمى بها كل يوم في أيام التشريق وما وقت الرمي؟", "سبع حصيات لكل جمرة من الجمرات الثلاث، ووقت الرمي من الزوال إلى غروب الشمس"]]}, {"n": 13, "m": 3, "i": "🌟", "t": "حِكم الحج وأسراره وتعظيم الشعائر", "B": [["الحِكم والأسرار", ["تظهر المساواة في أبهى صورها: المسلمون في مكان واحد ولباس واحد", "تلبية لأمر الله وتصديق لوعده بقبول دعوة إبراهيم عليه السلام", "تدريب على تحمّل المشاق النفسية والبدنية والمادية", "تحقق وحدة الأمة الإسلامية: الكل من جميع الأنحاء يجتمعون يدعون ربا واحدا", "تجرد من زينة الحياة الدنيا وإقبال على الله تعبدا ورغبة في مغفرته"]], ["تعظيم الشعائر", ["الحج من الطاعات التي يتقرب بها العبد إلى ربه ويتطهر بها من ذنوبه", "﴿ذلك ومن يعظم شعائر الله فإنها من تقوى القلوب﴾ (الحج 32)", "المسلم يجعل من حجه مدرسة يتعلم فيها التقوى"]], ["حديثان", ["«العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة» (البخاري)", "«خذوا عني مناسككم» (مسلم)"]], ["عادات جزائرية", ["وداع حجاج بيت الله الحرام واستقبالهم بعد عودتهم في جو مفعم بمشاعر الفرح والسرور"]]], "K": "الحج عبادة تجمع المساواة والوحدة والتجرد وتحمّل المشاق، وتعظيم شعائره من تقوى القلوب.", "M": ["حكم: مساواة، وحدة، تدريب على المشاق، تجرد من الدنيا", "الحج المبرور جزاؤه الجنة", "تعظيم الشعائر من التقوى"], "X": "يجتمع المسلمون في الحج بلباس واحد ومكان واحد وهدف واحد، فيتعلمون المساواة والصبر والتقوى.", "EX": [["لماذا أمرنا بالحج في وقت واحد ومكان واحد؟", "ليجتمع المسلمون من كل الأنحاء فتتحقق وحدة الأمة والمساواة بينهم، ويتعارفوا ويتعاونوا ويتدربوا على الطاعة الجماعية"], ["ما أثر الحج على الفرد والمجتمع؟", "على الفرد: تقوى وتطهر من الذنوب وصبر وتجرد من الدنيا. على المجتمع: وحدة وتعارف وتعاون ومساواة"], ["لماذا أمرنا الله بتعظيم شعيرة الحج؟", "لأنها من أعظم القربات في أشرف البقاع، وتعظيمها من دلالات التقوى كما في قوله ﴿فإنها من تقوى القلوب﴾، وبها يعود المسلم طاهرا من ذنوبه وخطاياه"], ["بما تفسر عادة وداع الحجاج واستقبالهم عند الجزائريين؟", "تعبّر عن محبة هذه الشعيرة وتعظيمها وفرحة المجتمع بأدائها، وتشجّع الآخرين على الحج والدعاء للحاج"]]}];
ZAD_EOF
cat > lessons_4am_isl.js <<'ZAD_EOF'
/* دروس التربية الإسلامية للسنة الرابعة متوسط (منشورات الشهاب). يُحمَّل بعد lessons.js و i4_data.js */
(function(){
  if(typeof LESSONS_DB==='undefined'||typeof I4_DATA==='undefined')return;
  var KEY='__KEY__';
  var SUB={'0':'₀','1':'₁','2':'₂','3':'₃','4':'₄','5':'₅','6':'₆','7':'₇','8':'₈','9':'₉','+':'₊','-':'₋','=':'₌','(':'₍',')':'₎','a':'ₐ','e':'ₑ','h':'ₕ','i':'ᵢ','j':'ⱼ','k':'ₖ','l':'ₗ','m':'ₘ','n':'ₙ','o':'ₒ','p':'ₚ','r':'ᵣ','s':'ₛ','t':'ₜ','u':'ᵤ','v':'ᵥ','x':'ₓ'};
  var SUP={'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹','+':'⁺','-':'⁻','=':'⁼','(':'⁽',')':'⁾','n':'ⁿ','i':'ⁱ','k':'ᵏ','p':'ᵖ','a':'ᵃ','m':'ᵐ'};
  function conv(s,map,pre){var o='';for(var i=0;i<s.length;i++){if(!map[s[i]])return pre+'('+s+')';o+=map[s[i]]}return o}
  function fx(s){
    return String(s).replace(/`/g,'').replace(/_\{([^}]*)\}/g,function(m,a){return conv(a,SUB,'_')}).replace(/\^\{([^}]*)\}/g,function(m,a){return conv(a,SUP,'^')});
  }
  function text(c){
    var t=[];
    c.B.forEach(function(b){t.push('▸ '+fx(b[0]));b[1].forEach(function(x){t.push('• '+fx(x))})});
    t.push('▸ للحفظ');t.push('• '+fx(c.K));
    t.push('▸ طرق وقواعد');c.M.forEach(function(x){t.push('• '+fx(x))});
    t.push('▸ شرح مبسط');t.push('• '+fx(c.X));
    t.push('▸ تمارين محلولة');
    c.EX.forEach(function(e,j){t.push('• تمرين '+(j+1)+': '+fx(e[0]));t.push('• الحل: '+fx(e[1]))});
    t.push('▸ المرجع');t.push('• كتاب التربية الإسلامية للسنة الرابعة متوسط (منشورات الشهاب) — الدرس '+c.m+': '+(I4_MQ[c.m]||'')+' — ملخص بتصرف');
    return t.join('\n');
  }
  var L=I4_DATA.map(function(c){var k=c.n<10?'0'+c.n:''+c.n;return {title:k+'. '+fx(c.t),content:text(c)}});
  var A=LESSONS_DB['4AM']=LESSONS_DB['4AM']||{};
  var o=A[KEY]||{};
  o.name=o.name||'التربية الإسلامية';
  o.lessons=L;
  o.maps='i4';
  A[KEY]=o;
})();
ZAD_EOF
cat > maps_i4.html <<'ZAD_EOF'
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>خرائط التربية الإسلامية - الرابعة متوسط</title>
<style>
/* Layout: sticky subject tabs; each lesson = a card with a three-column mind map (branches | centre | branches) joined by SVG curves; one column on phones. */
:root{
  --bg:#f4f5f7; --surface:#ffffff; --fg:#1d2330; --muted:#5d6678; --line:#d9dde5;
  --soft:#eceef3; --tabbg:#ffffff;
  --display:'Segoe UI',Tahoma,'Noto Naskh Arabic','Droid Arabic Naskh',system-ui,sans-serif; --body:'Segoe UI',Tahoma,'Noto Naskh Arabic','Droid Arabic Naskh',system-ui,sans-serif;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--bg:#12151c;--surface:#1a1e28;--fg:#e8ebf2;--muted:#a1a9ba;--line:#2f3544;--soft:#232837;--tabbg:#1a1e28;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#12151c;--surface:#1a1e28;--fg:#e8ebf2;--muted:#a1a9ba;--line:#2f3544;--soft:#232837;--tabbg:#1a1e28;color-scheme:dark}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--fg);font-family:var(--body);font-size:15px;line-height:1.7;
  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:0 40px}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--tabbg)}
.wrap{max-width:1180px;margin:0 auto}
header{padding:22px 0 8px}
h1{font-family:var(--display);font-size:clamp(24px,4vw,34px);margin:0;line-height:1.3;text-wrap:balance}
header p{margin:4px 0 0;color:var(--muted)}
nav.tabs{position:sticky;top:env(safe-area-inset-top,0px);z-index:9;background:var(--tabbg);border-bottom:1px solid var(--line);
  display:flex;gap:6px;overflow-x:auto;padding:8px 0;margin:8px 0 18px}
nav.tabs button{font:inherit;font-weight:700;border:1px solid var(--line);background:var(--surface);color:var(--fg);padding:6px 16px;border-radius:999px;cursor:pointer;white-space:nowrap}
nav.tabs button[aria-selected="true"]{background:var(--fg);color:var(--bg);border-color:var(--fg)}
button:focus-visible{outline:3px solid #3a6ea5;outline-offset:2px}
.axis{display:flex;align-items:center;gap:10px;margin:34px 0 14px;font-family:var(--display);font-size:22px}
.axis i{font-style:normal;font-size:26px}
.axis span.bar{flex:1;height:3px;border-radius:3px;background:var(--c)}
.axis b{color:var(--c)}
.card{background:var(--surface);border:1px solid var(--line);border-radius:14px;margin-bottom:22px;overflow:hidden}
.card>h2{margin:0;font-family:var(--display);font-size:17px;color:var(--c);padding:10px 16px;border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center;background:color-mix(in srgb,var(--c) 9%,var(--surface))}
.card>h2 small{color:var(--muted);font-family:var(--body);font-weight:600;font-size:13px;margin-inline-start:auto}
.map{position:relative;display:grid;grid-template-columns:1fr minmax(170px,230px) 1fr;gap:34px;align-items:center;padding:22px 18px}
.map svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.col{display:flex;flex-direction:column;gap:16px;position:relative;z-index:1}
.core{position:relative;z-index:1;text-align:center;background:var(--c);color:#fff;border-radius:50%/42%;padding:22px 14px;box-shadow:0 6px 18px color-mix(in srgb,var(--c) 40%,transparent)}
.core .ic{font-size:44px;line-height:1.1;display:block;margin-bottom:4px}
.core strong{font-family:var(--display);font-size:18px;line-height:1.5;display:block;text-wrap:balance}
.br{border:2px solid var(--bc);border-radius:12px;background:color-mix(in srgb,var(--bc) 8%,var(--surface));overflow:hidden}
.br h3{margin:0;background:var(--bc);color:#fff;font-size:14px;font-weight:700;padding:3px 12px}
.br ul{margin:0;padding:8px 12px;list-style:none;font-size:14px;line-height:1.6}
.br li{position:relative;padding-inline-start:14px;margin:2px 0}
.br li::before{content:"";position:absolute;inset-inline-start:0;top:.62em;width:7px;height:7px;border-radius:50%;background:var(--bc)}
.br li.t{padding:0;margin:0}.br li.t::before{display:none}
.br .sub{font-weight:700;color:var(--bc);margin-top:6px;font-size:13px}
.key{margin:0 18px 18px;padding:10px 14px;border-radius:10px;background:color-mix(in srgb,var(--c) 13%,var(--surface));border:1px dashed var(--c);font-weight:600}
.key b{color:var(--c)}
.extra{margin:0 18px 18px}
table{border-collapse:collapse;width:100%;font-size:14px}
th,td{border:1px solid var(--line);padding:5px 10px;text-align:start}
th{background:var(--c);color:#fff}
.tw{overflow-x:auto}
.more{border:1px solid var(--line);border-radius:10px;background:var(--surface)}.more summary{cursor:pointer;font-weight:700;padding:8px 14px;color:var(--c)}.more p{margin:0;padding:4px 14px 8px}.ev{margin:0;padding:0 14px 12px 14px;list-style:none}.ev li{padding:6px 10px;margin-top:6px;border-radius:8px;background:color-mix(in srgb,var(--c) 9%,var(--surface));font-size:16px;line-height:2}
.note{color:var(--muted);font-size:13px;margin-top:30px}
@media (max-width:760px){
  .map{grid-template-columns:1fr;gap:14px;padding:16px 12px}
  .map svg{display:none}
  .core{order:-1;border-radius:20px;padding:16px;display:flex;align-items:center;gap:12px;text-align:start}
  .core .ic{font-size:36px;margin:0}
  .col{gap:14px}
}
@media print{nav.tabs{display:none}}
.m{unicode-bidi:isolate;direction:ltr;font-family:'DejaVu Sans',system-ui,sans-serif;}.st{margin:4px 0;padding-right:10px;border-right:3px solid var(--c)}.m sub,.m sup{font-size:.7em}.ex{margin:10px 0;padding:8px 10px;border-radius:8px;background:color-mix(in srgb,var(--c) 7%,var(--surface))}.sol{margin-top:6px;padding-top:6px;border-top:1px dashed var(--c)}.how{margin-top:8px}</style></head><body>

<div class="wrap" dir="rtl">
<header>
  <h1>التربية الإسلامية - السنة الرابعة متوسط</h1>
  <p>مرتبة بحسب دروس الكتاب</p>
</header>
<nav class="tabs" id="tabs" role="tablist"></nav>
<main id="main"></main>
<p class="note">ملاحظة: هذه ملخصات ومراجعات مبنية على كتاب التربية الإسلامية للسنة الرابعة متوسط (منشورات الشهاب) ومصاغة بتصرف، والتمارين المحلولة من إعداد التطبيق. طابقها مع كتابك وتوجيهات أستاذك. طابقها مع كتابك وتوجيهات أستاذك.</p>
</div>
<script src="i4_data.js"></script>
<script>
const PAL=['#e4572e','#17a398','#3a6ea5','#c98a00','#8e44ad','#2e9e5b'];
const esc=s=>{
  const e=x=>String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  return String(s).split('`').map((p,i)=>{
    if(i%2===0)return e(p);
    return '<bdi dir="ltr" class="m">'+e(p).replace(/_\{([^}]*)\}/g,'<sub>$1</sub>').replace(/\^\{([^}]*)\}/g,'<sup>$1</sup>')+'</bdi>';
  }).join('');
};
const steps=t=>t.split(/\.\s+(?=\S)/).map(z=>z.replace(/\.$/,'')).filter(Boolean);
function branch(b,idx){
  const items=b[1].map(it=>'<li>'+esc(it)+'</li>').join('');
  return '<div class="br" data-br style="--bc:'+PAL[idx%PAL.length]+'"><h3>'+esc(b[0])+'</h3><ul>'+items+'</ul></div>';
}
function card(n,c,ic,t,bs,k,x,sub){
  const A=[],B=[];bs.forEach((b,i)=>(i%2?B:A).push(branch(b,i)));
  return '<section class="card" style="--c:'+c+'"><h2><span>'+ic+'</span>'+(n?'<span>'+n+'</span>':'')+'<small>'+(sub||'')+'</small></h2>'
  +'<div class="map"><svg aria-hidden="true"></svg><div class="col">'+A.join('')+'</div>'
  +'<div class="core" data-core><span class="ic">'+ic+'</span><strong>'+esc(t)+'</strong></div><div class="col">'+B.join('')+'</div></div>'
  +'<div class="key"><b>للحفظ:</b> '+esc(k)+'</div>'+(x?x:'')+'</section>';
}
function cardFor(l){
  const ex=l.EX.map((e,j)=>'<div class="ex"><b>تمرين '+(j+1)+':</b> '+esc(e[0])+'<div class="sol"><b>الحل:</b>'+steps(e[1]).map(z=>'<div class="st">'+esc(z)+'</div>').join('')+'</div></div>').join('');
  const x='<div class="extra"><b>طرق وقواعد:</b><ul>'+l.M.map(a=>'<li>'+esc(a)+'</li>').join('')+'</ul><div class="how"><b>شرح مبسط:</b> '+esc(l.X)+'</div></div><div class="extra"><b>تمارين محلولة بالتفصيل:</b>'+ex+'</div>';
  return card(l.n,I4_COL[l.m],l.i,l.t,l.B,l.K,x,(I4_SUB[l.m]||''));
}
function tab(m){return I4_DATA.filter(l=>l.m===m).map(cardFor).join('')}
const MS=Object.keys(I4_MQ).map(Number);
const tabs=document.getElementById('tabs'),main=document.getElementById('main');
function show(m){
  MS.forEach(i=>{document.getElementById('t-'+i).setAttribute('aria-selected',i===m)});
  main.innerHTML=tab(m);window.scrollTo(0,0);
  try{localStorage.setItem('i4tab',String(m))}catch(e){}
  requestAnimationFrame(draw);
}
MS.forEach(i=>{const b=document.createElement('button');b.id='t-'+i;b.role='tab';b.textContent=I4_ICO[i]+' '+I4_MQ[i];b.onclick=()=>show(i);tabs.appendChild(b)});
function draw(){
  document.querySelectorAll('.map').forEach(m=>{
    const svg=m.querySelector('svg');if(getComputedStyle(svg).display==='none')return;
    const r=m.getBoundingClientRect(),core=m.querySelector('[data-core]').getBoundingClientRect();
    const cx=core.left+core.width/2-r.left,cy=core.top+core.height/2-r.top;let p='';
    m.querySelectorAll('[data-br]').forEach(b=>{
      const q=b.getBoundingClientRect(),bx=q.left+q.width/2-r.left,by=q.top+q.height/2-r.top,right=bx>cx;
      const x1=right?q.left-r.left:q.right-r.left, x0=right?core.right-r.left:core.left-r.left, y0=cy+(by-cy)*0.15;
      const mx=(x0+x1)/2;
      p+='<path d="M'+x0+','+y0+' C'+mx+','+y0+' '+mx+','+by+' '+x1+','+by+'" fill="none" stroke="'+getComputedStyle(b).getPropertyValue('--bc')+'" stroke-width="3" stroke-linecap="round" opacity=".85"/>';
    });
    svg.innerHTML=p;
  });
}
addEventListener('resize',draw);
if(document.fonts&&document.fonts.ready)document.fonts.ready.then(draw);
let first=1;
try{const h=parseInt(location.hash.slice(1).replace(/\D/g,''),10);const s=parseInt(localStorage.getItem('i4tab'),10);if(MS.includes(h))first=h;else if(MS.includes(s))first=s}catch(e){}
show(first);
</script>
</body></html>
ZAD_EOF
cat > maps_i4_hook.js <<'ZAD_EOF'
/* فتح خرائط التربية الإسلامية 4AM (maps:'i4') من maps_i4.html؛ بقية المواد كما كانت. يُحمَّل بعد maps_hg_hook.js */
(function(){
  if(typeof openMaps!=='function')return;
  var o=openMaps;
  window.openMaps=function(k){
    try{var d=getSubjectData(k);if(d&&d.maps==='i4'){openWebview('maps_i4.html','🗺️ خرائط التربية الإسلامية - الرابعة متوسط');return}}catch(e){}
    return o(k);
  };
})();
